insert into public.library_items (slug, name_en, name_fil, aliases, material_code, resin_code, bin, summary_en, summary_fil, prep_en, prep_fil, note_en, note_fil, dont_en, dont_fil, hazard_en, hazard_fil, value, reuse_en, reuse_fil, reduce_en, reduce_fil, fact_en, fact_fil, related, detectable_class_key, sources, status, reviewed_by, reviewed_at) values
  ('aluminum-can', 'Aluminum can', 'Lata', array['can', 'soda can', 'softdrinks can', 'beer can', 'lata', 'tin can']::text[], 'MET-AL', null, 'recyclable', 'Empty it and crush it, then drop it in the blue bin.', null, '[{"title": "Empty it", "detail": "Make sure no drink is left inside."}, {"title": "Crush it", "detail": "Step on it or squeeze it to save space."}, {"title": "Sort it", "detail": "Drop it in the blue bin."}]'::jsonb, '[]'::jsonb, 'Empty it fully before sorting.', null, '{}'::text[], '{}'::text[], null, null, 'buys', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Aluminum can be recycled again and again without losing quality.', null, '{}'::text[], 'aluminum_can', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('bamboo-skewer', 'Chopsticks / bamboo skewer', 'Barbecue stick', array['chopsticks', 'skewer', 'barbecue stick', 'bbq stick', 'toothpick']::text[], 'WOO-RAW', null, 'biodegradable', 'Break sharp tips, then place it in the green bin.', null, '[]'::jsonb, '[]'::jsonb, 'Plastic chopsticks go in the black bin.', null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Untreated bamboo and wood break down naturally.', null, '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('banana-peel', 'Banana peel', 'Balat ng saging', array['banana', 'peel', 'fruit peel', 'saging', 'balat ng saging']::text[], 'ORG-FOOD', null, 'biodegradable', 'Remove stickers, then compost or use the green bin.', null, '[{"title": "Remove stickers", "detail": "Fruit stickers are plastic and go in the black bin."}, {"title": "Compost or green bin", "detail": "Add it to a compost pile or the green bin."}]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Organic material breaks down naturally.', null, '{}'::text[], 'banana_peel', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('battery', 'Battery', 'Baterya', array['batteries', 'aa battery', 'aaa battery', 'baterya', 'lithium battery', 'battery cell']::text[], 'BAT-ALK', null, 'hazardous', 'Tape the terminals. Take it to a battery collection point.', null, '[{"title": "Tape the terminals", "detail": "Cover both ends with tape to prevent sparks."}, {"title": "Bring it to a collection point", "detail": "Use the red bin or a battery drop-off."}]'::jsonb, '[]'::jsonb, 'Never mix with regular waste. Batteries can leak or start fires.', null, '{}'::text[], '{}'::text[], 'Batteries can leak harmful chemicals. Lithium-ion batteries can catch fire if crushed or punctured.', null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Batteries can leak or start fires. Never mix with regular waste.', null, '{}'::text[], 'battery', array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('broken-glass', 'Broken glass', 'Basag na salamin', array['glass shards', 'bubog', 'basag', 'broken bottle']::text[], 'GLA-BROKEN', null, 'residual', 'Wrap it well and label it "sharp". Give it to staff.', null, '[]'::jsonb, '[]'::jsonb, 'Never put loose broken glass in any bin.', null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Loose broken glass injures waste workers.', null, '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('cardboard', 'Cardboard', 'Karton', array['box', 'carton', 'karton', 'kahon', 'pizza box']::text[], 'PAP-BOARD', null, 'recyclable', 'Flatten it and keep it dry. Place it in the blue bin.', null, '[{"title": "Empty it", "detail": "Remove any contents, plastic wrap or foam."}, {"title": "Flatten it", "detail": "Open the flaps and fold it flat."}, {"title": "Keep it dry", "detail": "Put it in the blue bin away from wet waste."}]'::jsonb, '[]'::jsonb, 'Wet or greasy cardboard (e.g. pizza box bottom) goes in the black bin.', null, '{}'::text[], '{}'::text[], null, null, 'buys', array['Reuse it for storage or packing.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Dry cardboard is easy to recycle into new boxes. Wet or greasy cardboard is not.', null, '{}'::text[], 'cardboard', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('cigarette-butt', 'Cigarette butt', 'Upos', array['cigarette', 'upos', 'yosi', 'filter']::text[], 'PLA-7', 7, 'residual', 'Make sure it is fully out, then place it in the black bin.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Filters are plastic and contain toxins.', null, '{}'::text[], null, array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('coffee-grounds', 'Coffee grounds', 'Sapal ng kape', array['coffee', 'grounds', 'kape', 'tea leaves']::text[], 'ORG-FOOD', null, 'biodegradable', 'Place them in the green bin or compost.', null, '[]'::jsonb, '[]'::jsonb, 'Coffee pods and sachets go in the black bin.', null, '{}'::text[], '{}'::text[], null, null, null, array['Use them as garden fertilizer.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Coffee grounds are organic and compost well.', null, '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('diaper', 'Diaper', 'Lampin', array['diaper', 'nappy', 'lampin', 'adult diaper']::text[], 'MED-SAN', null, 'residual', 'Roll it up and tape it, then place it in the black bin.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Diapers are sanitary waste and can''t be recycled or composted.', null, '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('e-waste', 'E-waste (phones, cables, chargers)', 'E-waste', array['phone', 'cellphone', 'charger', 'cable', 'earphones', 'electronics', 'gadget']::text[], 'ELE-SMALL', null, 'hazardous', 'Do not throw it in any bin. Bring it to an e-waste collection point.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Electronics contain lead, mercury and other toxic parts, and many have batteries inside.', null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Electronics contain metals and chemicals that are harmful but valuable to recover.', null, '{}'::text[], null, array['S-RA9003-22', 'S-RA6969', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('eggshell', 'Eggshell', 'Balat ng itlog', array['egg', 'egg shell', 'itlog', 'balat ng itlog']::text[], 'ORG-BONE', null, 'biodegradable', 'Place it in the green bin or compost.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Crushed eggshells are good for garden soil.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Eggshells are organic and add calcium to compost.', null, '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('expired-medicine', 'Medicine / blister pack', 'Gamot', array['medicine', 'pills', 'tablets', 'blister pack', 'gamot', 'expired medicine', 'syrup']::text[], 'MED-DRUG', null, 'hazardous', 'Keep it in its pack. Bring it to a pharmacy or hazardous waste collection point.', null, '[{"title": "Keep it packed", "detail": "Leave pills in their blister or bottle."}, {"title": "Bring it to a drop-off", "detail": "Use a pharmacy take-back or a hazardous waste collection point."}]'::jsonb, '[]'::jsonb, 'Do not flush or throw it in regular bins.', null, '{}'::text[], '{}'::text[], 'Medicine can poison children or pets, and it pollutes water if flushed or thrown loose.', null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Medicines can poison water and soil if thrown away or flushed.', null, '{}'::text[], 'expired_medicine', array['S-RA9003-22', 'S-DOH-HCWM4']::text[], 'draft', '{}'::text[], null),
  ('face-mask', 'Face mask', 'Face mask', array['mask', 'surgical mask', 'facemask', 'kn95']::text[], 'MED-PPE', null, 'residual', 'Fold it inward, cut the ear loops, and place it in the black bin.', null, '[{"title": "Fold it inward", "detail": "Keep the used side inside."}, {"title": "Cut the ear loops", "detail": "Loops can trap animals."}, {"title": "Sort it", "detail": "Place it in the black bin."}]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Used masks may carry germs and are made of mixed materials that can''t be recycled.', null, '{}'::text[], 'face_mask', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('food-scraps', 'Food scraps', 'Tira-tirang pagkain', array['leftovers', 'food waste', 'rice', 'fruit peel', 'tira', 'tirang pagkain', 'kanin', 'mango peel']::text[], 'ORG-FOOD', null, 'biodegradable', 'Scrape food into the green bin. No plastic or packaging.', null, '[{"title": "Separate the packaging", "detail": "Take food out of wrappers and containers."}, {"title": "Scrape it in", "detail": "Put only the food in the green bin."}]'::jsonb, '[]'::jsonb, 'Remove any wrapper or container first.', null, '{}'::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Food waste can be composted. Mixed with plastic, it can''t.', null, '{}'::text[], 'food_scraps', array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('glass-bottle', 'Glass bottle', 'Boteng salamin', array['glass', 'bottle', 'jar', 'bote', 'boteng salamin', 'garapon']::text[], 'GLA-CONT', null, 'recyclable', 'Empty it and keep it whole. Place it in the blue bin.', null, '[{"title": "Empty it", "detail": "Pour out any liquid left inside."}, {"title": "Keep it whole", "detail": "Place it gently so it does not break."}, {"title": "Sort it", "detail": "Put it in the blue bin."}]'::jsonb, '[]'::jsonb, 'Broken glass: wrap it and give it to staff. Do not put it in any bin loose.', null, '{}'::text[], '{}'::text[], null, null, 'buys', array['Reuse it as a container or vase.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Whole glass bottles can be reused or remelted. Broken glass is a danger to waste workers.', null, '{}'::text[], 'glass_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-T2C']::text[], 'draft', '{}'::text[], null),
  ('ink-cartridge', 'Ink cartridge', 'Ink cartridge', array['printer ink', 'toner', 'cartridge', 'ink']::text[], 'ELE-ACC', null, 'hazardous', 'Bring it to a cartridge take-back or e-waste collection point.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Ink and toner can stain and irritate skin and eyes. Cartridges are e-waste.', null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Ink and electronics in cartridges are harmful in regular waste.', null, '{}'::text[], null, array['S-RA9003-22', 'S-DAO2013-22']::text[], 'draft', '{}'::text[], null),
  ('leaves', 'Leaves', 'Dahon', array['leaf', 'dry leaves', 'dahon', 'twigs', 'grass', 'garden waste']::text[], 'ORG-GARDEN', null, 'biodegradable', 'Place in the green bin or compost.', null, '[{"title": "Remove litter", "detail": "Pick out any plastic or wrappers mixed in."}, {"title": "Compost or green bin", "detail": "Leaves make good compost."}]'::jsonb, '[]'::jsonb, null, null, array['Don''t burn it']::text[], '{}'::text[], null, null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Garden waste breaks down into useful compost.', null, '{}'::text[], 'leaves', array['S-RA9003-22', 'S-RA9003-48']::text[], 'draft', '{}'::text[], null),
  ('light-bulb', 'Light bulb', 'Bombilya', array['bulb', 'lamp', 'fluorescent', 'led bulb', 'bombilya', 'ilaw']::text[], 'LIG-FLUO', null, 'hazardous', 'Keep it whole and wrap it. Give it to staff or a collection point.', null, '[{"title": "Keep it whole", "detail": "Do not break it."}, {"title": "Wrap it", "detail": "Use paper or its original box."}, {"title": "Hand it over", "detail": "Give it to staff or a hazardous waste collection point."}]'::jsonb, '[]'::jsonb, 'Fluorescent bulbs contain mercury. Do not break them.', null, '{}'::text[], '{}'::text[], 'Fluorescent tubes and CFLs contain mercury. A broken lamp releases mercury vapour.', null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Fluorescent bulbs contain mercury, which is toxic when released.', null, '{}'::text[], 'light_bulb', array['S-RA9003-22', 'S-RA9003-3PP', 'S-JAO-LAMPS']::text[], 'draft', '{}'::text[], null),
  ('paint-can', 'Paint can', 'Lata ng pintura', array['paint', 'pintura', 'thinner', 'solvent']::text[], 'HHW-PAINT', null, 'hazardous', 'Keep it closed. Bring it to a hazardous waste collection point.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], 'Leftover paint and thinner are flammable and toxic. Never pour them down a drain.', null, null, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Leftover paint and solvents are toxic.', null, '{}'::text[], null, array['S-RA9003-22', 'S-RA9003-3PP']::text[], 'draft', '{}'::text[], null),
  ('paper-bag', 'Paper bag', 'Supot na papel', array['paper bag', 'brown bag', 'takeout bag', 'supot', 'supot na papel']::text[], 'PAP-CLEAN', null, 'recyclable', 'Empty it and flatten it, then drop it in the blue bin.', null, '[{"title": "Check the bag", "detail": "Keep it only if it is clean, dry and intact."}, {"title": "Give it another use", "detail": "Use it for dry storage or your next shopping trip."}, {"title": "Recycle when worn out", "detail": "Empty and flatten it, then use the blue bin."}]'::jsonb, '[]'::jsonb, 'Greasy or food-soaked paper goes in the black bin.', null, '{}'::text[], '{}'::text[], null, null, 'accepts', array['Reuse it first. If it is still clean and sturdy, keep it for another trip. Recycle it when it is no longer usable.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Reusing extends the life of paper fibers. Clean, dry paper can then be recycled; grease-soaked paper cannot.', null, '{}'::text[], 'paper_bag', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('paper-cup', 'Paper cup', 'Papel na baso', array['coffee cup', 'paper cup', 'hot cup']::text[], 'PAP-COAT', null, 'residual', 'Empty it, then place it in the black bin.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Bring a reusable tumbler next time.']::text[], '{}'::text[], array['Bring your own mug or tumbler']::text[], '{}'::text[], 'Paper cups have a plastic lining, so they can''t be recycled with paper.', null, '{}'::text[], null, array['S-RA9003-22', 'S-QC-SP2876']::text[], 'draft', '{}'::text[], null),
  ('paper-sheet', 'Paper', 'Papel', array['paper', 'bond paper', 'notebook paper', 'papel', 'scratch paper', 'printout']::text[], 'PAP-CLEAN', null, 'recyclable', 'Keep it dry and uncrumpled. Place it in the blue bin.', null, '[{"title": "Use both sides", "detail": "Scratch paper still has a blank side for notes."}, {"title": "Keep it dry and flat", "detail": "Do not crumple or wet it."}, {"title": "Sort it", "detail": "Place it in the blue bin."}]'::jsonb, '[]'::jsonb, 'Wet or food-stained paper goes in the black bin.', null, '{}'::text[], '{}'::text[], null, null, 'buys', array['Use the blank side for notes.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Clean, flat paper has long fibers that recycle well.', null, '{}'::text[], 'paper_sheet', array['S-RA9003-22', 'S-RA9003-3Z']::text[], 'draft', '{}'::text[], null),
  ('pen', 'Pen', 'Ballpen', array['ballpen', 'ball pen', 'marker', 'highlighter']::text[], 'PLA-7', 7, 'residual', 'Place it in the black bin.', null, '[]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, null, array['Use refillable pens.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Pens mix plastic, metal and ink, so they aren''t recycled here.', null, '{}'::text[], null, array['S-RA9003-22']::text[], 'draft', '{}'::text[], null),
  ('plastic-bottle', 'Plastic bottle', 'Plastik na bote', array['bottle', 'water bottle', 'pet bottle', 'softdrinks bottle', 'bote', 'plastik na bote', 'mineral water']::text[], 'PLA-1', 1, 'recyclable', 'Empty it, remove the cap, and flatten it. Drop it in the blue bin.', null, '[{"title": "Empty it", "detail": "Pour out any drink left inside."}, {"title": "Remove the cap", "detail": "Caps are a different plastic. Put the cap in the blue bin separately."}, {"title": "Flatten it", "detail": "Squeeze out the air to save space, then use the blue bin."}]'::jsonb, '[]'::jsonb, 'If it has leftover drink, empty and rinse it first.', null, array['Don''t burn it']::text[], '{}'::text[], null, null, 'buys', array['Refill it for water or use it for plant cuttings.']::text[], '{}'::text[], array['Bring a refillable tumbler', 'Use water refill stations']::text[], '{}'::text[], 'PET bottles are widely recycled when they are empty and clean. Leftover liquid spoils other recyclables.', null, '{}'::text[], 'plastic_bottle', array['S-RA9003-22', 'S-RA9003-3Z', 'S-QC-T2C', 'S-STD-RIC']::text[], 'draft', '{}'::text[], null),
