  ('plastic-utensil', 'Plastic utensil', 'Plastik na kubyertos', array['spoon', 'fork', 'plastic spoon', 'plastic fork', 'kutsara', 'tinidor', 'kubyertos']::text[], 'PLA-6', 6, 'residual', 'Place it in the black bin.', null, '[{"title": "Reuse if you can", "detail": "Wash it and keep it for another meal."}, {"title": "Sort it", "detail": "When worn out, place it in the black bin."}]'::jsonb, '[]'::jsonb, null, null, '{}'::text[], '{}'::text[], null, null, 'none', array['Wash and reuse it if it is still intact.']::text[], '{}'::text[], array['Bring your own spoon and fork']::text[], '{}'::text[], 'Small single-use plastics are too small and mixed to recycle here.', null, '{}'::text[], 'plastic_utensil', array['S-RA9003-22', 'S-QC-SP2876']::text[], 'draft', '{}'::text[], null),
