insert into public.library_local_rules (lgu, item_slug, material_code, note_en, note_fil, sources, status) values
  ('QC', 'plastic-bottle', null, 'In Quezon City: trade PET bottles for Environmental Points at Trash to Cashback booths.', null, array['S-QC-T2C']::text[], 'draft'),
